                candidates.append((mm, st_mm, dd, score, mc_ch))

        candidates.sort(key=lambda c: c[3])

        chosen = None
        for cand in candidates:
            mm, st, dd, score, mc_ch = cand
            if mc_ch and mc_used + mc_ch > max_mc:
                continue
            chosen = cand
            break

        if chosen is None:
