        mm, st, dd, score, mc_ch = chosen
        en = st + dd

        mc_used += mc_ch
        shift_l1_used += abs(st - base_start)

        new_schedule[(j, o)] = {"job": j, "op": o, "machine": mm, "start": st, "end": en, "dur": dd}
        machine_intervals.setdefault(mm, []).append((st, en))

    makespan = max(r["end"] for r in new_schedule.values())
    return new_schedule, makespan, mc_used, shift_l1_used

# Exhaustive search over parameters
best_result = None
